CREATE TABLE public.usuario_acceso_temporal (user_id uuid PRIMARY KEY, org_id uuid REFERENCES public.organizations(id), pendiente boolean NOT NULL DEFAULT true, asignada_en timestamptz NOT NULL DEFAULT now(), cambiada_en timestamptz, asignada_por uuid NOT NULL);
GRANT SELECT ON public.usuario_acceso_temporal TO authenticated; GRANT ALL ON public.usuario_acceso_temporal TO service_role;
ALTER TABLE public.usuario_acceso_temporal ENABLE ROW LEVEL SECURITY;
CREATE POLICY propio ON public.usuario_acceso_temporal FOR SELECT TO authenticated USING(user_id=(SELECT auth.uid()));
CREATE OR REPLACE FUNCTION public.requiere_cambio_temporal() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT coalesce((SELECT pendiente FROM public.usuario_acceso_temporal WHERE user_id=auth.uid()),false) $$;
REVOKE ALL ON FUNCTION public.requiere_cambio_temporal() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.requiere_cambio_temporal() TO authenticated;
CREATE OR REPLACE FUNCTION public.marcar_password_temporal(_usuario uuid,_org uuid,_actor uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.role()<>'service_role' THEN RAISE EXCEPTION 'Solo el servidor registra contraseñas temporales'; END IF; INSERT INTO public.usuario_acceso_temporal(user_id,org_id,pendiente,asignada_por) VALUES(_usuario,_org,true,_actor) ON CONFLICT(user_id) DO UPDATE SET pendiente=true,asignada_en=now(),cambiada_en=NULL,asignada_por=_actor,org_id=_org; INSERT INTO public.audit_trail(user_id,org_id,tabla,registro_id,accion,motivo,valor_nuevo) VALUES(_actor,_org,'usuario_acceso_temporal',_usuario::text,'TEMPORAL_ASIGNADA','Alta con contraseña temporal',jsonb_build_object('pendiente',true)); END $$;
CREATE OR REPLACE FUNCTION public.confirmar_password_temporal(_usuario uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE org uuid; BEGIN IF auth.role()<>'service_role' THEN RAISE EXCEPTION 'Solo el servidor confirma el cambio de contraseña'; END IF; UPDATE public.usuario_acceso_temporal SET pendiente=false,cambiada_en=now() WHERE user_id=_usuario AND pendiente RETURNING org_id INTO org; IF FOUND THEN INSERT INTO public.audit_trail(user_id,org_id,tabla,registro_id,accion,motivo,valor_anterior,valor_nuevo) VALUES(_usuario,org,'usuario_acceso_temporal',_usuario::text,'CONTRASENA_CAMBIADA','Primer acceso: cambio obligatorio',jsonb_build_object('pendiente',true),jsonb_build_object('pendiente',false)); END IF; END $$;
REVOKE ALL ON FUNCTION public.marcar_password_temporal(uuid,uuid,uuid),public.confirmar_password_temporal(uuid) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.marcar_password_temporal(uuid,uuid,uuid),public.confirmar_password_temporal(uuid) TO service_role;
CREATE OR REPLACE FUNCTION public.s1_acceso_previo() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.role()='authenticated' AND public.requiere_cambio_temporal() AND coalesce(current_setting('request.path',true),'') NOT IN ('/rpc/requiere_cambio_temporal') THEN RAISE EXCEPTION 'Debes cambiar tu contraseña temporal antes de usar la plataforma' USING ERRCODE='42501'; END IF; END $$;
REVOKE ALL ON FUNCTION public.s1_acceso_previo() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.s1_acceso_previo() TO authenticated,anon,service_role;
ALTER ROLE authenticator SET pgrst.db_pre_request='public.s1_acceso_previo';
NOTIFY pgrst,'reload config';
CREATE TABLE public.curso_diploma_config (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),curso_id uuid NOT NULL REFERENCES public.cursos(id),version integer NOT NULL,instructor_user_id uuid,instructor_nombre text NOT NULL,instructor_cargo text NOT NULL,firma_png text NOT NULL,motivo text NOT NULL,created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(curso_id,version));
GRANT SELECT ON public.curso_diploma_config TO authenticated; GRANT ALL ON public.curso_diploma_config TO service_role;
ALTER TABLE public.curso_diploma_config ENABLE ROW LEVEL SECURITY;
CREATE POLICY leer ON public.curso_diploma_config FOR SELECT TO authenticated USING(true);
CREATE OR REPLACE FUNCTION public.guardar_firma_diploma(_curso uuid,_instructor uuid,_nombre text,_cargo text,_firma text,_motivo text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE prev public.curso_diploma_config; nid uuid; BEGIN PERFORM pg_advisory_xact_lock(hashtextextended(_curso::text,820)); SELECT * INTO prev FROM public.curso_diploma_config WHERE curso_id=_curso ORDER BY version DESC LIMIT 1; IF auth.uid() IS NULL OR NOT (public.is_super_admin() OR (prev.instructor_user_id=auth.uid() AND _instructor=prev.instructor_user_id)) THEN RAISE EXCEPTION 'Solo el super administrador o el instructor cambia la firma del diploma'; END IF; IF length(btrim(coalesce(_motivo,'')))<5 THEN RAISE EXCEPTION 'Motivo obligatorio (mínimo 5 caracteres)'; END IF; IF coalesce(_firma,'') NOT LIKE 'data:image/png;base64,%' OR length(_firma)>2000000 OR btrim(coalesce(_nombre,''))='' OR btrim(coalesce(_cargo,''))='' THEN RAISE EXCEPTION 'Selecciona una firma PNG y completa nombre y cargo'; END IF; IF _instructor IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=_instructor AND activo) THEN RAISE EXCEPTION 'Instructor no disponible'; END IF; PERFORM set_config('tracea.firma_diploma_rpc','1',true); INSERT INTO public.curso_diploma_config(curso_id,version,instructor_user_id,instructor_nombre,instructor_cargo,firma_png,motivo,created_by) VALUES(_curso,coalesce(prev.version,0)+1,_instructor,btrim(_nombre),btrim(_cargo),_firma,btrim(_motivo),auth.uid()) RETURNING id INTO nid; INSERT INTO public.audit_trail(user_id,org_id,tabla,registro_id,accion,motivo,valor_anterior,valor_nuevo) VALUES(auth.uid(),public.get_user_org_id(),'curso_diploma_config',nid::text,'FIRMA_DIPLOMA_CONFIGURADA',btrim(_motivo),CASE WHEN prev.id IS NOT NULL THEN to_jsonb(prev)-'firma_png' END,jsonb_build_object('curso_id',_curso,'version',coalesce(prev.version,0)+1,'instructor_nombre',_nombre,'instructor_user_id',_instructor,'firma_sha256',encode(sha256(convert_to(_firma,'UTF8')),'hex'))); RETURN nid; END $$;
REVOKE ALL ON FUNCTION public.guardar_firma_diploma(uuid,uuid,text,text,text,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.guardar_firma_diploma(uuid,uuid,text,text,text,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.firma_diploma_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF TG_OP<>'INSERT' OR coalesce(current_setting('tracea.firma_diploma_rpc',true),'')<>'1' THEN RAISE EXCEPTION 'La firma conserva su historial; usa la configuración del diploma'; END IF; RETURN NEW; END $$;
CREATE TRIGGER guard BEFORE INSERT OR UPDATE OR DELETE ON public.curso_diploma_config FOR EACH ROW EXECUTE FUNCTION public.firma_diploma_guard();